export const CRON_JOBS = ["/api/cron/summaries", "/api/cron/reviews", "/api/cron/agent-backlog", "/api/cron/bank-sync", "/api/cron/scalable-sync", "/api/cron/scalable-history", "/api/cron/chat-titles"] as const;
