  const url = read("NEXT_PUBLIC_SUPABASE_URL");
  const key = read("NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY");
  if (!url && !key) {
    return {
      status: "missing",
      detail: "Moneo isn't set up yet. In the Moneo folder, run npm run setup, then restart Moneo.",
    };
  }
  if (!url || !key) {
